import{_ as e,c as i,o as l,ah as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免费易经学习文档。","frontmatter":{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免费易经学习文档。"},"headers":[],"relativePath":"zh/articles/yilin/index.md","filePath":"zh/articles/yilin/index.md"}'),t={name:"zh/articles/yilin/index.md"};function n(o,a,s,p,d,h){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="焦氏易林" tabindex="-1">焦氏易林 <a class="header-anchor" href="#焦氏易林" aria-label="Permalink to “焦氏易林”">​</a></h1><p>《焦氏易林》又称《易林》，传为西汉易学家 <strong>焦延寿（字赣）</strong> 所作的诗体占书（作者归属亦有不同说法）。 它以《周易》六十四卦为基础，将「本卦 → 之卦」的组合系统化：<strong>每一卦各衍生六十四卦</strong>，合成 <strong>64×64＝4096</strong> 条占辞， 多用<strong>四言韵语</strong>呈现，把抽象卦象转写成更具画面感的意象与情境。</p><h2 id="与《周易》的故事线" tabindex="-1">与《周易》的故事线 <a class="header-anchor" href="#与《周易》的故事线" aria-label="Permalink to “与《周易》的故事线”">​</a></h2><p>《周易》重在卦象与卦爻辞的义理结构；而《易林》则像是一套「把卦意变成可读的诗句」的占筮语料库：</p><ul><li>以诗句补足卦象的情境（人事、物象、吉凶、得失）</li><li>让占断更容易抓住「象」与「机」</li><li>也成为后世象数易学与占筮实作的重要材料之一</li></ul><h2 id="本-app-如何使用《易林》" tabindex="-1">本 App 如何使用《易林》 <a class="header-anchor" href="#本-app-如何使用《易林》" aria-label="Permalink to “本 App 如何使用《易林》”">​</a></h2><p>本 App 会依你占得的「本卦 → 之卦」自动显示对应诗句，用来辅助解读：</p><ol><li>先抓诗中的关键意象（人物、动作、地点、器物、吉凶词）</li><li>再对照你的问题脉络与当下处境</li><li>最后回到《周易》卦象与动爻，做整体判断</li></ol><h2 id="翻译说明" tabindex="-1">翻译说明 <a class="header-anchor" href="#翻译说明" aria-label="Permalink to “翻译说明”">​</a></h2><p>英文诗句为中文整理翻译而来，偏直译；中文仍应作为主要依据，英文仅供参考。</p><ul><li>读法：先观诗中关键意象，再结合当事问题、卦象与动爻综合判读。</li><li>来源说明：英文翻译从中文本《焦氏易林》整理翻译而来，诗句以直译为主，难以完全传达中文之准确含义；以中文为准，英文仅供参考。</li></ul>',11)])])}const m=e(t,[["render",n]]);export{_ as __pageData,m as default};
